#if defined(__riscv_vector)
        // Vectorized approach:
        // The computation is: a[k] = a[k+1] * a[k] for k in [i, i+4]
        // Groups of 5 are independent. We can vectorize across groups.
        // For each group, we need 6 input elements to compute 5 outputs.
        // We load 6*VL elements, shift by 1, multiply, store 5*VL elements.

        size_t vl;
        vfloat32m1_t v_in, v_shifted, v_out;

        while (i + 5 <= limit) {
            int remaining_groups = (limit - i) / 5;
            if (remaining_groups == 0) break;

            // Set vector length for the number of groups
            vl = __riscv_vsetvl_e32m1(remaining_groups);
            if (vl == 0) break;

            // We need to load 6 elements per group, but RVV loads contiguous elements.
            // The pattern is: for group j (0 to vl-1), we need a[i+5*j] to a[i+5*j+5].
            // This is not contiguous across groups.
            // 
            // Alternative: Process the array as a single contiguous block.
            // The operation is: result[k] = input[k+1] * input[k] for k in [i, i+5*vl-1].
            // But we only want to update every 5th group? No, we want to update all.
            // Actually, the loop processes i, i+1, i+2, i+3, i+4, then i+5, i+6, ...
            // So it's contiguous! The groups are just logical divisions.
            // We can process the entire range [i, limit] as a contiguous block.
            // Operation: a[k] = a[k+1] * a[k] for k from i to limit-1.
            // But the original loop does this in chunks of 5, and stops at limit.
            // limit = LEN_1D - 5, so we process up to LEN_1D - 6.
            // The last group starts at limit-4, and uses a[limit] to a[limit+4].
            // Wait, let's re-examine:
            // for (i = 0; i < LEN_1D - 5; i += 5)
            //   a[i] = a[i+1] * a[i]
            //   ...
            //   a[i+4] = a[i+5] * a[i+4]
            // So we process indices 0 to LEN_1D-6 (inclusive) for the left side.
            // The right side goes up to LEN_1D-1.
            //
            // We can vectorize the entire range [i, limit) as a contiguous block.
            // Load limit - i + 1 elements (to have a[k+1] for the last k).
            // Shift by 1, multiply, store limit - i elements.

            int count = limit - i;
            if (count <= 0) break;

            // Load count + 1 elements
            v_in = __riscv_vle32_v_f32m1(&a[i], count + 1);

            // Shift left by 1 (slide up) to get a[k+1]
            // vslideup_vx shifts elements up, inserting 0 at the bottom.
            // We want a[k+1] at position k, so we slide up by 1.
            v_shifted = __riscv_vslideup_vx_f32m1(v_in, 1, count + 1);

            // Multiply: result[k] = a[k+1] * a[k]
            v_out = __riscv_vfmul_vv_f32m1(v_shifted, v_in, count + 1);

            // Store count elements (we don't need the last product)
            __riscv_vse32_v_f32m1(&a[i], v_out, count);

            i += count;
        }
