            // If c[i] >= 0.0, we take the 'then' branch -> update a
            mask = __riscv_vmfge_vf_f32m1_b32(vc, 0.0f, vl);

            // Compute d[i] * e[i] and d[i] * d[i]
            vfloat32m1_t de_prod = __riscv_vfmul_vv_f32m1(vd, ve, vl);
            vfloat32m1_t dd_prod = __riscv_vfmul_vv_f32m1(vd, vd, vl);

            // For mask == true (c[i] >= 0): a[i] = c[i] + d[i]*e[i]
            vfloat32m1_t new_a = __riscv_vfadd_vv_f32m1(vc, de_prod, vl);
            va = __riscv_vmerge_vvm_f32m1(new_a, va, mask, vl);

            // For mask == false (c[i] < 0): b[i] = a[i] + d[i]*d[i]
            // Note: We use the original 'va' loaded from memory for the calculation of b
            // because in the scalar code, if we go to L20, we use the current value of a[i].
            // The vector merge above updated 'va' only where mask is true.
            // Where mask is false, 'va' still holds the old value from memory, which is correct.
            vfloat32m1_t new_b = __riscv_vfadd_vv_f32m1(va, dd_prod, vl);

            // Invert mask using vector not operation for boolean type
            vbool32_t not_mask = __riscv_vnot_b32(mask, vl);
            vb = __riscv_vmerge_vvm_f32m1(new_b, vb, not_mask, vl);

            // Store results
            __riscv_vse32_v_f32m1(a + i, va, vl);
            __riscv_vse32_v_f32m1(b + i, vb, vl);

            i += vl;
        }
        #else
        // Fallback to scalar code if RVV is not available
        for (; i < len; ++i) {
            if (c[i] < (real_t)0.) {
                b[i] = a[i] + d[i] * d[i];
            } else {
                a[i] = c[i] + d[i] * e[i];
            }
        }
        #endif

        dummy(a, b, c, d, e, aa, bb, cc, 0.);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
